items=re.findall(r'^pub (?:enum|type|trait|struct) (\w+)',text,re.M)
trait=text.split('pub trait PublicDataHost',1)[1].split('\npub struct',1)[0];members=re.findall(r'^    fn (\w+)',trait,re.M)
