mapping={'constructor':'new','onMessage':'on_message','handleTickerEvents':'handle_ticker_events','handleFundingRateEvents':'handle_funding_rate_events','listenOHLCV':'listen_ohlcv','listenOrderBook':'listen_order_book','dispose':'dispose','connectAndSubscribe':'connect_and_subscribe','onOpen':'on_open','ping':'ping','subscribe':'subscribe','#onMarketsChanged':'on_markets_changed'}
