common=' Evidence: tests/public_stream_data_oracle.cjs runs the maintained class, base capabilities and real DefaultStore; tests/public_stream_data.rs asserts native model fields/numeric bits, live callback arrays, shared parsed objects, reentry, retained handles and decoded frame arguments before wire traces. Scoped enumeration stops at 87 source cases plus explicit native lifetime/Vec probes. Shared UTF-8 string boundary: sdk-rs/parity/MANIFEST-SPEC.md#shared-utf8-string-boundary.'
notes={
'BlofinPublicWebsocket':('divergent','CHOSEN: complete public facade composes every source startup/watchdog/dispatch/listener/disposal body, with explicit inherited base/socket/Store/timer/emitter capabilities. Default broadcast callbacks use Weak facade references to prevent self-owning Rc cycles: source retaining its ticker callback keeps it callable (last becomes999), whereas dropping the Rust facade makes the retained callback a no-op (last stays100). Listener closures capture host/model handles directly and a Weak lifetime probe proves no installed-listener self-cycle. Owned topic arrays in the previously declared onMarketsChanged boundary remain unchanged.'),
'BlofinPublicWebsocket.constructor':('ported','Same base constructor first, empty topics, one ticker and one funding handler, any-message keepalive=true, notified=false/undefined timeout, and captured base-close handler invoked before arming the inherited watchdog. Base-close failure prevents watchdog scheduling; repeated close retains the original base callback.'),
'BlofinPublicWebsocket.onMessage':('divergent','MIXED: matching disposed/establishment/track/pong order, first exact compact channel token, ack suppression, instId search starting at channel end, broadcast-before-exact routing, inherited constructor-handler TypeError, live handler-array append and shared mutable parsed-object callbacks. FORCED: valid ASCII JSON containing an escaped lone surrogate parses to native UTF-16 D800 in source, while serde Value refuses it; the direct source unit witness runs before encoding. Canonical sdk-rs/parity/MANIFEST-SPEC.md#shared-utf8-string-boundary and sdk-rs/parity/MANIFEST-SPEC.md#forced-surrogate-conflict apply. CHOSEN: shared bounded parser rejects depth130 instead of source dispatching leaf42; retains recursion budget. Both native refusals are explicit witnesses, not omitted comparisons.'),
'BlofinPublicWebsocket.handleTickerEvents':('ported','Same first update only; parseFloat open/last/bid/ask/volumes, roundUSD percentage, last reused for mark/index, zero openInterest, and typed numeric ModelPatch to actual Store.updateTicker. Malformed numeric strings, signed zero, Infinity, null/array coercion, missing market and coercion/shape errors are native assertions; no JSON serialization of numeric patch values.'),
'BlofinPublicWebsocket.handleFundingRateEvents':('ported','Same first update only, id lookup and parseFloat fundingRate/fundingTime patch into actual Store.updateTicker; timestamp stays in native milliseconds. Signed zero, NaN, prefix/array coercion and missing ticker are exercised.'),
'BlofinPublicWebsocket.listenOHLCV':('divergent','CHOSEN: Rust owns OHLCVOptions snapshots; source keeps the caller option object live across 100ms loading retries and inside the secondary parser. Mutating source opts.symbol to missing before the retry yields no handlers, whereas the already-owned native opts still subscribe BTC candle/books5; explicitly witnessed. Otherwise matches array/object candle fallback, integer timestamp and volume precedence, finite-number rejection, full-field duplicate suppression, mutable retained Candle handles, same-bin median close bridge, warning on invalid snapshots, string book level indexing, shared topics, delayed connection retry, repeated cleanup and discarded inner cleanup after loading retry. Rc model handles release guards before callbacks, including nested candle dispatch.'),
'BlofinPublicWebsocket.listenOrderBook':('divergent','CHOSEN: retained native book root is a mutable shared Rc handle, but nested bids/asks Vec snapshots are owned; source retained bids array alias sees a books5 head replacement99->97 while a native cloned Vec remains99. Root book aliases DO observe updates and cleanup in both runtimes. Preserves snapshot replacement, amount-first zero skips, iterable string levels, seq chain/one-shot gap resubscribe, reset after sends, last-price filtering, indexed totals, incremental top-N overwrite with retained tails and partial writes on a later coercion error. Guards are released before user callbacks and resubscribe sends; callback cleanup and send reentry have source/native witnesses.'),
'BlofinPublicWebsocket.dispose':('ported','Same truthy timeout cancellation/reset, markets:changed listener removal, then inherited disposal, with strict ordering and first host error propagation. Numeric zero timer remains; no added isDisposed guard. Clear/off/super failures retain matching native intermediate state.'),
}
parts=s.split('[[symbol]]');header=parts[0];out=[header];new_rows=0
for body in parts[1:]:
 row=tomllib.loads('[[symbol]]'+body)['symbol'][0];ts=row['ts'];targets=row['rs'] if isinstance(row['rs'],list) else ([] if not row['rs'] else [row['rs']]);changed=False
 if ts in notes:
  status,note=notes[ts];assert row['status']=='pending';new_rows+=1
  if ts=='BlofinPublicWebsocket':targets=[rsfile+'::'+item for item in items]+[rsfile+'::PublicDataHost::'+m for m in members]+[rsfile+'::BlofinPublicWebsocket::on_close']
  else:targets=[rsfile+'::BlofinPublicWebsocket::'+mapping[ts.split('.',1)[1]]]
  for key,value in [('layer','mirror'),('rs',targets),('status',status),('note',note+common)]:body=re.sub(r'^'+key+r' = .*$',key+' = '+json.dumps(value,ensure_ascii=False),body,flags=re.M)
  changed=True
 else:
  member=ts.removeprefix('BlofinPublicWebsocket.')
  if ts=='BlofinPublicWebsocket#onMarketsChanged':member='#onMarketsChanged'
  if member in mapping:
   target=rsfile+'::BlofinPublicWebsocket::'+mapping[member];assert target not in targets;targets.append(target);body=re.sub(r'^rs = .*$', 'rs = '+json.dumps(targets),body,flags=re.M)
   note=row['note'].replace('not the pending facade','with the completed public facade').replace('Does not claim the pending onMessage routing body.','Inbound routing is now in public_stream_data.').replace('Base lifecycle, inbound dispatch and listeners are not claimed by this row.','')
   body=re.sub(r'^note = .*$', 'note = '+json.dumps(note+' Composed facade wrapper delegates to this body in public_stream_data; original body and status unchanged.'),body,flags=re.M)
 out.append('[[symbol]]'+body)
assert new_rows==8
s=''.join(out);data=tomllib.loads(s);files=sorted({target.split('::')[0]for row in data['symbol']for target in (row['rs']if isinstance(row['rs'],list)else [row['rs']])if target});s=re.sub(r'^rust_files = .*$', 'rust_files = '+json.dumps(files),s,flags=re.M);p.write_text(s)
print('mapped8 rows,4 ported/4 divergent')
